import boto3
from typing import List, Dict, Any

def extract_tables_and_row_structure(file_bytes: bytes) -> List[Dict[str, Any]]:
    """
    Extracts table cells and row structure from a document using AWS Textract.
    """
    textract_client = boto3.client('textract')

    response = textract_client.analyze_document(
        Document={'Bytes': file_bytes},
        FeatureTypes=['TABLES']
    )

    blocks = response['Blocks']
    block_map = {block['Id']: block for block in blocks}

    extracted_tables = []

    for block in blocks:
        if block['BlockType'] == 'TABLE':
            table_cells = []

            for rel in block.get('Relationships', []):
                if rel['Type'] == 'CHILD':
                    for child_id in rel['Ids']:
                        cell_block = block_map.get(child_id)
                        if cell_block and cell_block['BlockType'] == 'CELL':
                            cell_text = ""
                            for cell_rel in cell_block.get('Relationships', []):
                                if cell_rel['Type'] == 'CHILD':
                                    for text_id in cell_rel['Ids']:
                                        text_block = block_map.get(text_id)
                                        if text_block and text_block['BlockType'] in ('WORD', 'LINE'):
                                            cell_text += text_block['Text'] + " "

                            table_cells.append({
                                'row_index': cell_block.get('RowIndex', 0),
                                'column_index': cell_block.get('ColumnIndex', 0),
                                'text': cell_text.strip(),
                                'row_span': cell_block.get('RowSpan', 1),
                                'column_span': cell_block.get('ColumnSpan', 1)
                            })

            row_structure = {}
            max_col = 0

            for cell in table_cells:
                r_idx = cell['row_index']
                c_idx = cell['column_index']

                if r_idx not in row_structure:
                    row_structure[r_idx] = {}

                row_structure[r_idx][c_idx] = cell
                max_col = max(max_col, c_idx)

            formatted_rows = []
            for r_idx in sorted(row_structure.keys()):
                row = []
                for c_idx in range(1, max_col + 1):
                    row.append(row_structure[r_idx].get(c_idx, {
                        'row_index': r_idx, 
                        'column_index': c_idx, 
                        'text': '', 
                        'row_span': 1, 
                        'column_span': 1
                    }))
                formatted_rows.append(row)

            extracted_tables.append({
                'table_id': block['Id'],
                'row_count': len(formatted_rows),
                'column_count': max_col,
                'rows': formatted_rows
            })

    return extracted_tables
